class MovieRentingSystem { using Item=tuple<int,int,int>;map<int,set<Item>> available;set<Item> rented;unordered_map<long long,int> prices;long long key(int shop,int movie){return ((long long)shop<<32)|(unsigned int)movie;}Item item(int shop,int movie){return {prices[key(shop,movie)],shop,movie};}public: MovieRentingSystem(int n,vector<vector<int>>& entries){for(auto& value:entries){prices[key(value[0],value[1])]=value[2];available[value[1]].insert({value[2],value[0],value[1]});}}vector<int> search(int movie){vector<int> answer;for(auto [price,shop,id]:available[movie]){if(answer.size()==5)break;answer.push_back(shop);}return answer;}void rent(int shop,int movie){auto value=item(shop,movie);available[movie].erase(value);rented.insert(value);}void drop(int shop,int movie){auto value=item(shop,movie);rented.erase(value);available[movie].insert(value);}vector<vector<int>> report(){vector<vector<int>> answer;for(auto [price,shop,movie]:rented){if(answer.size()==5)break;answer.push_back({shop,movie});}return answer;} };
